    # reported the four figure functions as dead when eir_figures dispatches
    # over them by reference.
    _orphans = sorted(
        n for n in _defs
        if len(_re.findall(r'(?<!def )' + _re.escape(n) + r'\s*\(', _src)) == 0
        and len(_re.findall(r'(?<!def )(?<![\w.])' + _re.escape(n)
                            + r'(?!\s*\()(?![\w])', _src)) == 0)
    if _orphans:
        _warn.append(f"{len(_orphans)} function(s) defined and never called: "
                     f"{', '.join(_orphans[:8])}"
                     + (' ...' if len(_orphans) > 8 else ''))

    # 2e. error swallowing
    _bare = len(_re.findall(r'\n\s*except:\s*\n', _src))
    _pass = len(_re.findall(r'except Exception:\s*\n\s*pass', _src))
    if _bare:
        _fail.append(f"{_bare} bare `except:` clause(s): a defect in the code "
                     f"becomes an empty result with no message")
    if _pass:
        _warn.append(f"{_pass} `except Exception: pass` clause(s)")

